class Solution {
    public int[][] soften(int[][] image) {
        int m = image.length, n = image[0].length;
        int[][] out = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int total = 0, count = 0;
                for (int rr = Math.max(0, r - 1); rr <= Math.min(m - 1, r + 1); rr++)
                    for (int cc = Math.max(0, c - 1); cc <= Math.min(n - 1, c + 1); cc++) {
                        total += image[rr][cc];
                        count++;
                    }
                out[r][c] = total / count;
            }
        }
        return out;
    }
}

