class Solution:
    def soften(self, image: List[List[int]]) -> List[List[int]]:
        m, n = len(image), len(image[0])
        for r in range(m):
            for c in range(n):
                total = count = 0
                for rr in range(max(0, r - 1), min(m, r + 2)):
                    for cc in range(max(0, c - 1), min(n, c + 2)):
                        total += image[rr][cc] & 255
                        count += 1
                image[r][c] |= (total // count) << 8
        for row in image:
            for c in range(n):
                row[c] >>= 8
        return image

